// ============ 思路：枚举所有子列 ============
//
// 一个子列由"左端 i"和"右端 j"唯一确定，那就把 i、j 的所有组合都试一遍，
// 再把 i 到 j 之间的数加起来。
//
//   数组： -2  11  -4  13  -5  -2
//           0   1   2   3   4   5
//
//   左端 i=0 时：试 j=0,1,2,...,5        （6 个子列）
//   左端 i=1 时：试 j=1,2,...,5          （5 个子列）
//   ...
//   一共 N(N+1)/2 个子列
//
// 然后每个子列还要从头加一遍，最坏要加 N 次 —— 所以是 O(N³)。
//
// 注意不是无脑的 N³ 次循环：实际的比较次数是 N(N+1)(N+2)/6，
// 但常数不影响量级，写成 O(N³) 就够了。
//
// ============ 这层循环在干嘛 ============
//
//   i：子列左端
//   j：子列右端
//   k：把 i..j 之间重新加一遍 ← **这一层是多余的**
//
// 记住这个 k 循环，下一个算法就是把它省掉。

// 返回最大子列和；全负时返回 0
// const int A[] 表示"只读"，函数不会改调用者的数组
int MaxSubseqSum1(const int A[], int N)
{
// 当前子列的和
    int thisSum;
// 至今为止的最大值，从 0 开始（对应"空子列"）
    int maxSum = 0;
// 左端、右端、累加下标
    int i, j, k;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 枚举右端
        for (j = i; j < N; j++)
        {
// 把 i..j 重新加一遍 —— 这一层是浪费的
            thisSum = 0;
            for (k = i; k <= j; k++)
            {
                thisSum += A[k];
            }
// 更大就记下来
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}

