// ============ 关键观察 ============
//
// 算法 1 里，固定左端 i 之后，j 从 i 慢慢涨上去，
// 每换一个 j 就把 i..j 从头重加一遍 —— 但上一轮的加和明明还能用！
//
//     j=i   ：A[i]
//     j=i+1 ：A[i] + A[i+1]           = 上一轮的和 + A[i+1]
//     j=i+2 ：A[i] + A[i+1] + A[i+2]   = 上一轮的和 + A[i+2]
//
// 所以把 thisSum 提到 j 循环**外面**、每轮只加**一个新元素**，
// 内层那个 k 循环就没了 —— O(N³) 直接降到 O(N²)。
//
// ============ 这是最常见的优化手法 ============
//
// 找出"重复计算的部分"，把它缓存下来复用。
// 后面动态规划、前缀和、滑动窗口，本质都是这个思路。
// 区别只在于"缓存什么、怎么复用"。

// 返回最大子列和
int MaxSubseqSum2(const int A[], int N)
{
// 当前和
    int thisSum;
// 最大值
    int maxSum = 0;
// 左端、右端
    int i, j;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 每换一个左端，重新开始累加
        thisSum = 0;

// 右端向右推进
        for (j = i; j < N; j++)
        {
// 只加"新进来的那个元素" —— 不再重头加
            thisSum += A[j];

// 边加边比较，所以不需要第三层循环
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}

