// ============ 全部代码只有这么几行 ============
//
//    for (i = 0; i < N; i++) {
//        thisSum += A[i];
//        if (thisSum > maxSum) maxSum = thisSum;
//        else if (thisSum < 0) thisSum = 0;
//    }
//
// 但它凭什么对？
//
// ============ 为什么"和为负就扔掉"是对的 ============
//
// 假设扫到某个位置时 thisSum 已经变成负数了。
// 那么对于**后面任何一个**子列来说，如果它包含了这一段负的和，
// 把它去掉只会更大 —— 所以这一段永远不需要再被带上。
//
//   数组：  3  -5  2  4
//           ↑
//   扫到 -5 时 thisSum = 3 + (-5) = -2 < 0
//
//   后面不管接什么，带着这 -2 都不如不带。
//   所以干脆从下一个位置重新开始数。
//
// ============ "在线"是什么意思 ============
//
// 它只需要**读一遍**数据，而且每读一个数就能立刻给出"到目前为止的答案"。
// 就算数据是一个一个流过来、存不下来，它照样能算。
//
// 这种性质叫**在线算法（online algorithm）**。
// 前三个算法都做不到 —— 它们必须先把整个数组拿在手里反复看。
//
// ============ 顺带一提 ============
//
// 这个算法和"最大子段和"的动态规划写法是同一个东西：
//
//   dp[i] = max(A[i], dp[i-1] + A[i])
//
// 只不过这里用 thisSum 把 dp 数组省成了一个变量 —— 空间从 O(N) 降到 O(1)。

// 返回最大子列和
int MaxSubseqSum4(const int A[], int N)
{
// 当前正在累加的这一段的和
    int thisSum = 0;
// 至今为止的最大值
    int maxSum = 0;
// 扫描下标
    int i;

// 从头扫到尾，只扫一遍
    for (i = 0; i < N; i++)
    {
// 先把当前元素加进来
        thisSum += A[i];

// 变大了就更新答案
// 注意这一步在"判负"之前 —— 因为加上一个正数之后可能刚好是最大值。
        if (thisSum > maxSum)
        {
            maxSum = thisSum;
        }
// 变成负的就没用了，扔掉重来
// 用 else if 而不是 if：两者不可能同时成立（thisSum 不可能既大于 maxSum
// 又小于 0，因为 maxSum 至少是 0）。写成两个 if 也不会错，但没必要。
        else if (thisSum < 0)
        {
            thisSum = 0;
        }
    }

// 返回
    return maxSum;
}

