// ============ 为什么要"四个答案互相对账" ============
//
// 这四个算法思路完全不同，但它们**必须算出同一个数**。
// 如果有一个不一样，那一定是写错了 —— 这种"多解法互验"是很有用的调试手段，
// 尤其在你不确定哪个对的时候。
//
// 然后看代码长度：从 30 行缩到 8 行，复杂度从 O(N³) 降到 O(N)。
// 这就是"好的算法"值钱的地方。

// 测试数据：有正有负，答案应该是 20（11 + (-4) + 13）
static const int kData[] = { -2, 11, -4, 13, -5, -2 };
// 元素个数
#define N ((int)(sizeof(kData) / sizeof(kData[0])))

// 主函数
int main(void)
{
// 四个算法的结果
    int r1, r2, r3, r4;

// 打印输入
    {
        int i;
        printf("输入: ");
        for (i = 0; i < N; i++)
        {
            printf("%d ", kData[i]);
        }
        printf("\n\n");
    }

// 逐个跑，并打印各自的答案
// 手工的算法分析看不出快慢，但把 N 放大到几万时，四个算法的耗时差别是
// 天壤之别（O(N³) 要跑几分钟，O(N) 一瞬间）。这里数据小，只对比答案。
    r1 = MaxSubseqSum1(kData, N);
    printf("算法1 三重循环 O(N^3)   -> %d\n", r1);

    r2 = MaxSubseqSum2(kData, N);
    printf("算法2 两重循环 O(N^2)   -> %d\n", r2);

    r3 = MaxSubseqSum3(kData, 0, N - 1);
    printf("算法3 分治     O(NlogN) -> %d\n", r3);

    r4 = MaxSubseqSum4(kData, N);
    printf("算法4 在线处理 O(N)     -> %d\n", r4);

// 四个答案必须一致
    printf("\n");
    if (r1 == r2 && r2 == r3 && r3 == r4)
    {
        printf("四种算法答案一致：%d\n", r1);
    }
    else
    {
        printf("答案不一致 —— 有算法写错了！\n");
    }

// 边界情况：全是负数
// 题目约定"空子列的和为 0"，所以全负时答案是 0 而不是最大的那个负数。
    {
        static const int neg[] = { -3, -1, -7, -2 };
        int n = (int)(sizeof(neg) / sizeof(neg[0]));
        printf("\n全是负数时: %d %d %d %d\n",
               MaxSubseqSum1(neg, n), MaxSubseqSum2(neg, n),
               MaxSubseqSum3(neg, 0, n - 1), MaxSubseqSum4(neg, n));
        printf("（约定：空子列的和为 0，所以答案是 0）\n");
    }

// 正常结束
    return 0;
}

