#include <stdio.h>

// ============ 思路：枚举所有子列 ============
//
// 一个子列由"左端 i"和"右端 j"唯一确定，那就把 i、j 的所有组合都试一遍，
// 再把 i 到 j 之间的数加起来。
//
//   数组： -2  11  -4  13  -5  -2
//           0   1   2   3   4   5
//
//   左端 i=0 时：试 j=0,1,2,...,5        （6 个子列）
//   左端 i=1 时：试 j=1,2,...,5          （5 个子列）
//   ...
//   一共 N(N+1)/2 个子列
//
// 然后每个子列还要从头加一遍，最坏要加 N 次 —— 所以是 O(N³)。
//
// 注意不是无脑的 N³ 次循环：实际的比较次数是 N(N+1)(N+2)/6，
// 但常数不影响量级，写成 O(N³) 就够了。
//
// ============ 这层循环在干嘛 ============
//
//   i：子列左端
//   j：子列右端
//   k：把 i..j 之间重新加一遍 ← **这一层是多余的**
//
// 记住这个 k 循环，下一个算法就是把它省掉。

// 返回最大子列和；全负时返回 0
// const int A[] 表示"只读"，函数不会改调用者的数组
int MaxSubseqSum1(const int A[], int N)
{
// 当前子列的和
    int thisSum;
// 至今为止的最大值，从 0 开始（对应"空子列"）
    int maxSum = 0;
// 左端、右端、累加下标
    int i, j, k;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 枚举右端
        for (j = i; j < N; j++)
        {
// 把 i..j 重新加一遍 —— 这一层是浪费的
            thisSum = 0;
            for (k = i; k <= j; k++)
            {
                thisSum += A[k];
            }
// 更大就记下来
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}

// ============ 关键观察 ============
//
// 算法 1 里，固定左端 i 之后，j 从 i 慢慢涨上去，
// 每换一个 j 就把 i..j 从头重加一遍 —— 但上一轮的加和明明还能用！
//
//     j=i   ：A[i]
//     j=i+1 ：A[i] + A[i+1]           = 上一轮的和 + A[i+1]
//     j=i+2 ：A[i] + A[i+1] + A[i+2]   = 上一轮的和 + A[i+2]
//
// 所以把 thisSum 提到 j 循环**外面**、每轮只加**一个新元素**，
// 内层那个 k 循环就没了 —— O(N³) 直接降到 O(N²)。
//
// ============ 这是最常见的优化手法 ============
//
// 找出"重复计算的部分"，把它缓存下来复用。
// 后面动态规划、前缀和、滑动窗口，本质都是这个思路。
// 区别只在于"缓存什么、怎么复用"。

// 返回最大子列和
int MaxSubseqSum2(const int A[], int N)
{
// 当前和
    int thisSum;
// 最大值
    int maxSum = 0;
// 左端、右端
    int i, j;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 每换一个左端，重新开始累加
        thisSum = 0;

// 右端向右推进
        for (j = i; j < N; j++)
        {
// 只加"新进来的那个元素" —— 不再重头加
            thisSum += A[j];

// 边加边比较，所以不需要第三层循环
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}

// ============ 分治的思路 ============
//
// 把数组从中间切成两半，那么最大子列只可能出现在三个地方：
//
//   ① 完全在左半边
//   ② 完全在右半边
//   ③ 跨过中线（左半的一部分 + 右半的一部分）
//
//   数组： -2  11  -4 │ 13  -5  -2
//                     ↑ 中线
//
// ① 和 ② 就是递归 —— 把左右两半各自当成一个更小的问题。
// ③ 只能硬算，但有个好办法：从中线出发往两边扫。
//
// ============ 跨界那部分怎么算 ============
//
// 跨界的子列一定**包含中线两侧紧邻的元素**，而且是从中线往两边连续延伸的。
// 所以：
//
//   往左扫：从中线开始往左累加，记录"左边的最大后缀和"
//   往右扫：从中线右边开始往右累加，记录"右边的最大前缀和"
//   两者相加 = 跨界的最大和
//
// 各扫一遍是 O(N)，加上递归的两半 T(N/2)：
//
//   T(N) = 2·T(N/2) + O(N)   →   O(N log N)
//
// ============ 代价 ============
//
// 比算法 2 快，但代码复杂得多，而且递归要占栈空间。
// 更要命的是：**下一个算法只要 8 行代码，还是 O(N)**。

// 从 left 到 right（闭区间）的最大子列和
// 注意参数是下标范围，不是数组长度 —— 递归时左右两半传不同的范围
int MaxSubseqSum3(const int A[], int left, int right)
{
// 中线
    int mid;
// 左半、右半、跨界的结果
    int leftSum, rightSum, crossSum;
// 往左扫、往右扫的累加值与最大值
    int maxLeft, maxRight, sum;
// 循环用
    int i;

// 递归出口：只剩一个元素
    if (left == right)
    {
// 单个负数对"最大和"没有贡献（还不如空子列 0），所以返回 0。
        return A[left] > 0 ? A[left] : 0;
    }

// 从中线劈开
    mid = (left + right) / 2;

// ① 左半边的最大子列和
    leftSum = MaxSubseqSum3(A, left, mid);

// ② 右半边的最大子列和
    rightSum = MaxSubseqSum3(A, mid + 1, right);

// ③ 跨过中线的最大子列和：先从中线往左扫
// 从中线开始**往左**累加（i 递减），一路记录最大值。
// 这样得到的是"以中线结尾的最大后缀和"。
    maxLeft = 0;
    sum = 0;
    for (i = mid; i >= left; i--)
    {
        sum += A[i];
        if (sum > maxLeft)
        {
            maxLeft = sum;
        }
    }

// 再从中线右边往右扫
// 同理，得到"从中线右边开始的最大前缀和"。
// 左边后缀 + 右边前缀，拼起来就是跨界的最大和 —— 而且它一定是连续的。
    maxRight = 0;
    sum = 0;
    for (i = mid + 1; i <= right; i++)
    {
        sum += A[i];
        if (sum > maxRight)
        {
            maxRight = sum;
        }
    }

// 跨界的结果
    crossSum = maxLeft + maxRight;

// 三者取最大
// 手写两次比较，就不用再引一个 max3 函数了。
    if (leftSum < rightSum)
    {
        leftSum = rightSum;
    }
    if (leftSum < crossSum)
    {
        leftSum = crossSum;
    }

// 返回
    return leftSum;
}

// ============ 全部代码只有这么几行 ============
//
//    for (i = 0; i < N; i++) {
//        thisSum += A[i];
//        if (thisSum > maxSum) maxSum = thisSum;
//        else if (thisSum < 0) thisSum = 0;
//    }
//
// 但它凭什么对？
//
// ============ 为什么"和为负就扔掉"是对的 ============
//
// 假设扫到某个位置时 thisSum 已经变成负数了。
// 那么对于**后面任何一个**子列来说，如果它包含了这一段负的和，
// 把它去掉只会更大 —— 所以这一段永远不需要再被带上。
//
//   数组：  3  -5  2  4
//           ↑
//   扫到 -5 时 thisSum = 3 + (-5) = -2 < 0
//
//   后面不管接什么，带着这 -2 都不如不带。
//   所以干脆从下一个位置重新开始数。
//
// ============ "在线"是什么意思 ============
//
// 它只需要**读一遍**数据，而且每读一个数就能立刻给出"到目前为止的答案"。
// 就算数据是一个一个流过来、存不下来，它照样能算。
//
// 这种性质叫**在线算法（online algorithm）**。
// 前三个算法都做不到 —— 它们必须先把整个数组拿在手里反复看。
//
// ============ 顺带一提 ============
//
// 这个算法和"最大子段和"的动态规划写法是同一个东西：
//
//   dp[i] = max(A[i], dp[i-1] + A[i])
//
// 只不过这里用 thisSum 把 dp 数组省成了一个变量 —— 空间从 O(N) 降到 O(1)。

// 返回最大子列和
int MaxSubseqSum4(const int A[], int N)
{
// 当前正在累加的这一段的和
    int thisSum = 0;
// 至今为止的最大值
    int maxSum = 0;
// 扫描下标
    int i;

// 从头扫到尾，只扫一遍
    for (i = 0; i < N; i++)
    {
// 先把当前元素加进来
        thisSum += A[i];

// 变大了就更新答案
// 注意这一步在"判负"之前 —— 因为加上一个正数之后可能刚好是最大值。
        if (thisSum > maxSum)
        {
            maxSum = thisSum;
        }
// 变成负的就没用了，扔掉重来
// 用 else if 而不是 if：两者不可能同时成立（thisSum 不可能既大于 maxSum
// 又小于 0，因为 maxSum 至少是 0）。写成两个 if 也不会错，但没必要。
        else if (thisSum < 0)
        {
            thisSum = 0;
        }
    }

// 返回
    return maxSum;
}

// ============ 为什么要"四个答案互相对账" ============
//
// 这四个算法思路完全不同，但它们**必须算出同一个数**。
// 如果有一个不一样，那一定是写错了 —— 这种"多解法互验"是很有用的调试手段，
// 尤其在你不确定哪个对的时候。
//
// 然后看代码长度：从 30 行缩到 8 行，复杂度从 O(N³) 降到 O(N)。
// 这就是"好的算法"值钱的地方。

