#include <stdio.h>


// 返回最大子列和；全负时返回 0
int MaxSubseqSum1(const int A[], int N)
{
// 当前子列的和
    int thisSum;
// 至今为止的最大值，从 0 开始（对应"空子列"）
    int maxSum = 0;
// 左端、右端、累加下标
    int i, j, k;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 枚举右端
        for (j = i; j < N; j++)
        {
// 把 i..j 重新加一遍 —— 这一层是浪费的
            thisSum = 0;
            for (k = i; k <= j; k++)
            {
                thisSum += A[k];
            }
// 更大就记下来
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}


// 返回最大子列和
int MaxSubseqSum2(const int A[], int N)
{
// 当前和
    int thisSum;
// 最大值
    int maxSum = 0;
// 左端、右端
    int i, j;

// 枚举左端
    for (i = 0; i < N; i++)
    {
// 每换一个左端，重新开始累加
        thisSum = 0;

// 右端向右推进
        for (j = i; j < N; j++)
        {
// 只加"新进来的那个元素" —— 不再重头加
            thisSum += A[j];

// 边加边比较，所以不需要第三层循环
            if (thisSum > maxSum)
            {
                maxSum = thisSum;
            }
        }
    }

// 返回
    return maxSum;
}


// 从 left 到 right（闭区间）的最大子列和
int MaxSubseqSum3(const int A[], int left, int right)
{
// 中线
    int mid;
// 左半、右半、跨界的结果
    int leftSum, rightSum, crossSum;
// 往左扫、往右扫的累加值与最大值
    int maxLeft, maxRight, sum;
// 循环用
    int i;

// 递归出口：只剩一个元素
    if (left == right)
    {
        return A[left] > 0 ? A[left] : 0;
    }

// 从中线劈开
    mid = (left + right) / 2;

// ① 左半边的最大子列和
    leftSum = MaxSubseqSum3(A, left, mid);

// ② 右半边的最大子列和
    rightSum = MaxSubseqSum3(A, mid + 1, right);

// ③ 跨过中线的最大子列和：先从中线往左扫
    maxLeft = 0;
    sum = 0;
    for (i = mid; i >= left; i--)
    {
        sum += A[i];
        if (sum > maxLeft)
        {
            maxLeft = sum;
        }
    }

// 再从中线右边往右扫
    maxRight = 0;
    sum = 0;
    for (i = mid + 1; i <= right; i++)
    {
        sum += A[i];
        if (sum > maxRight)
        {
            maxRight = sum;
        }
    }

// 跨界的结果
    crossSum = maxLeft + maxRight;

// 三者取最大
    if (leftSum < rightSum)
    {
        leftSum = rightSum;
    }
    if (leftSum < crossSum)
    {
        leftSum = crossSum;
    }

// 返回
    return leftSum;
}


// 返回最大子列和
int MaxSubseqSum4(const int A[], int N)
{
// 当前正在累加的这一段的和
    int thisSum = 0;
// 至今为止的最大值
    int maxSum = 0;
// 扫描下标
    int i;

// 从头扫到尾，只扫一遍
    for (i = 0; i < N; i++)
    {
// 先把当前元素加进来
        thisSum += A[i];

// 变大了就更新答案
        if (thisSum > maxSum)
        {
            maxSum = thisSum;
        }
// 变成负的就没用了，扔掉重来
        else if (thisSum < 0)
        {
            thisSum = 0;
        }
    }

// 返回
    return maxSum;
}


